"""Return an ordered keep mask and one finite margin per proposed call."""
# Input validation
if not all(isinstance(arr, np.ndarray) for arr in [logp_with_result, logp_call_only, logp_no_call]):
    raise ValueError("Inputs must be numpy arrays")
if logp_with_result.ndim != 2 or logp_call_only.ndim != 2 or logp_no_call.ndim != 2:
    raise ValueError("Inputs must be 2D matrices")
if not (logp_with_result.shape == logp_call_only.shape == logp_no_call.shape):
    raise ValueError("Shape mismatch")
n, m = logp_with_result.shape
if n == 0 or m == 0:
    raise ValueError("Empty matrix")
if not (np.isfinite(logp_with_result).all() and np.isfinite(logp_call_only).all() and np.isfinite(logp_no_call).all()):
    raise ValueError("Inputs contain nonfinite values")
if (logp_with_result > 0).any() or (logp_call_only > 0).any() or (logp_no_call > 0).any():
    raise ValueError("Inputs contain positive values")
if isinstance(tau_filter, bool) or not np.isscalar(tau_filter) or not np.isreal(tau_filter) or not np.isfinite(tau_filter) or tau_filter < 0:
    raise ValueError("Invalid threshold")
# Compute margin as the maximum total improvement over no-call baseline
margin_with = np.sum(logp_with_result - logp_no_call, axis=1)
margin_call = np.sum(logp_call_only - logp_no_call, axis=1)
margins = np.maximum(margin_with, margin_call)
keep = margins > tau_filter
return keep, margins

